import{_ as l,o as a,c as o,a2 as t}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"编码风格","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/coding-style.md","filePath":"zh/dev/coding-style.md"}'),i={name:"zh/dev/coding-style.md"};function d(c,e,r,s,h,n){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="编码风格" tabindex="-1">编码风格 <a class="header-anchor" href="#编码风格" aria-label="Permalink to &quot;编码风格&quot;">​</a></h1><p>这棵树是自洽的；与它保持一致。</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><ul><li>C11（<code>-std=gnu11</code>），4 空格缩进，K&amp;R 花括号，.c/.h 中没有 制表符。</li><li>类型：内核的定宽集合（<code>u8/u16/u32/u64/s8/...</code>、<code>types.h</code>） - 而非 uint8_t 拼法。</li><li>类型要紧处每行一个声明；能初始化就初始化。</li><li>每个文件以 SPDX + 版权注释块开篇，并带一段说明该文件为何 存在的 Purpose 段落。未来的读者（以及文档生成器）依赖它。</li><li>函数注释：契约、参数、返回码 - 尤其是每一个负数返回值。</li><li>错误处理：检查、以清晰的消息报告并回退 - 绝不泄漏半初始化 的设备注册。</li></ul><h2 id="汇编" tabindex="-1">汇编 <a class="header-anchor" href="#汇编" aria-label="Permalink to &quot;汇编&quot;">​</a></h2><ul><li><code>.S</code> 文件（经预处理）：boot.S 与各架构蹦床是参考。在每个 入口点注释 ABI。</li></ul><h2 id="shell-命令" tabindex="-1">shell 命令 <a class="header-anchor" href="#shell-命令" aria-label="Permalink to &quot;shell 命令&quot;">​</a></h2><ul><li>用 <code>shell_register_command_ex</code> + 工作包标签注册，让 <code>help -w</code> 保持真实。</li><li>一行帮助，参数错误时打印 <code>usage:</code>，失败时非零退出。</li><li>仅 ASCII。</li></ul><h2 id="命名" tabindex="-1">命名 <a class="header-anchor" href="#命名" aria-label="Permalink to &quot;命名&quot;">​</a></h2><ul><li>文件：<code>kernel/&lt;area&gt;/core_&lt;thing&gt;.c</code>、<code>drivers/&lt;bus&gt;/driver_&lt;hw&gt;.c</code>、 <code>shell/shell_cmds_&lt;domain&gt;.c</code>、<code>fs/fs_&lt;fs&gt;.c</code> - 树的布局就是 分类法（文档生成器按它分组）。</li><li>符号：<code>&lt;module&gt;_&lt;verb&gt;_&lt;object&gt;</code>（如 <code>driver_block_flush</code>、 <code>klog_write</code>、<code>ota_ab_install</code>）。静态辅助函数保持文件内 私有。</li><li>带模块前缀的全大写常量（<code>OC_MB2_TAG_END</code>、 <code>SHELL_MAX_COMMANDS</code>）。</li></ul><h2 id="限额是设计的一部分" tabindex="-1">限额是设计的一部分 <a class="header-anchor" href="#限额是设计的一部分" aria-label="Permalink to &quot;限额是设计的一部分&quot;">​</a></h2><p>当你新增一张有界表时，限额常量要带一条解释这个数字的注释 （见 shell.h 里的 <code>SHELL_MAX_COMMANDS</code> - 232-&gt;256 的历史记录在 定义处）。保持这个纪律：下一个调整它的人需要这个故事。</p><h2 id="不要做的事" tabindex="-1">不要做的事 <a class="header-anchor" href="#不要做的事" aria-label="Permalink to &quot;不要做的事&quot;">​</a></h2><ul><li>不留&quot;以备后用&quot;的死代码 - 删掉；git 记得。</li><li>不做静默截断 - 带消息拒绝（alias 值是榜样：要么完整存储要么 拒绝）。</li><li>不写不带 BUG- 编号或工作包引用的 <code>// TODO</code>。</li><li>不引入新的第三方代码：这棵树是原创的、Apache 2.0，并保持 如此。</li></ul>',14)])])}const m=l(i,[["render",d]]);export{u as __pageData,m as default};
